sys_script.script:
(function executeRule(current, previous) {
    var proposalId = current.getUniqueValue();
    var desiredCount = parseInt(current.getValue('option_year_count') || '0', 10);
    // Total periods needed: 1 Base Year (seq 0) + desiredCount Option Years (seq 1..N)
    var totalPeriods = desiredCount + 1;

    // Get existing periods ordered by sequence
    var existingSeqs = {};
    var existingCount = 0;
    var periodGr = new GlideRecord('x_942105_costima_0_period');
    periodGr.addQuery('proposal', proposalId);
    periodGr.orderBy('period_sequence');
    periodGr.query();
    while (periodGr.next()) {
        existingSeqs[parseInt(periodGr.getValue('period_sequence') || '0', 10)] = true;
        existingCount++;
    }

    // Create missing periods
    if (existingCount < totalPeriods) {
        for (var seq = 0; seq < totalPeriods; seq++) {
            if (!existingSeqs[seq]) {
                var newPeriod = new GlideRecord('x_942105_costima_0_period');
                newPeriod.initialize();
                newPeriod.setValue('proposal', proposalId);
                newPeriod.setValue('period_sequence', seq);
                if (seq === 0) {
                    newPeriod.setValue('period_type', 'base_year');
                    newPeriod.setValue('period_name', 'Base Year');
                } else {
                    newPeriod.setValue('period_type', 'option_year');
                    newPeriod.setValue('period_name', 'Option Year ' + seq);
                }
                newPeriod.insert();
            }
        }
    }

    // Delete excess periods (reduction already validated in before rule)
    if (existingCount > totalPeriods) {
        var deleteGr = new GlideRecord('x_942105_costima_0_period');
        deleteGr.addQuery('proposal', proposalId);
        deleteGr.addQuery('period_sequence', '>=', totalPeriods);
        deleteGr.query();
        while (deleteGr.next()) {
            deleteGr.deleteRecord();
        }
    }
})(current, previous);
